const parts = $json.payload.parts || [];

function decodeBase64(data) {
  data = data.replace(/-/g, "+").replace(/_/g, "/");
  return Buffer.from(data, "base64").toString("utf-8");
}

function cleanText(text) {
  return text
    // Remove CSS and scripts
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<script[\s\S]*?<\/script>/gi, "")

    // Remove HTML tags
    .replace(/<[^>]*>/g, " ")

    // Remove invisible characters
    .replace(/[\u200B-\u200F\u2060\uFEFF\u00AD]/g, "")

    // Replace common HTML entities
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")

    // Remove extra spaces
    .replace(/\s+/g, " ")

    .replace(/\s{2,}/g, " ")
    .trim();
}

function isGoodEmail(text) {
  const badPatterns = [
    "body, table, td",
    "font-family"
  ];

  return (
    text.length > 100 &&
    !badPatterns.some(pattern => text.includes(pattern))
  );
}


// Find email parts
const plainPart = parts.find(
  part => part.mimeType === "text/plain"
);

const htmlPart = parts.find(
  part => part.mimeType === "text/html"
);


let email = "";


// Some emails don't have parts
if (!parts.length && $json.payload.body?.data) {
  email = cleanText(
    decodeBase64($json.payload.body.data)
  );
}

// 1. Try plain text first
if (plainPart?.body?.data) {
  email = cleanText(
    decodeBase64(plainPart.body.data)
  );
}


// 2. If plain text is bad, use HTML
if (!isGoodEmail(email) && htmlPart?.body?.data) {
  email = cleanText(
    decodeBase64(htmlPart.body.data)
  );
}


const headers = $json.payload.headers || [];

const from = headers.find(h => h.name === "From")?.value || "";
const subject = headers.find(h => h.name === "Subject")?.value || "";

return [{
  json: {
    sender: from,
    subject: subject,
    email: email
  }
}];

let email = $json.email;

// Remove everything after common footer markers
const footerMarkers = [
  "unsubscribe",
  "privacy policy",
  "privacy notice",
  "terms of service",
  "terms apply",
  "view in browser",
  "manage preferences",
  "all rights reserved",
  "copyright",
  "©",
  "help center"
];

const lower = email.toLowerCase();

let cutIndex = email.length;

for (const marker of footerMarkers) {
  const index = lower.indexOf(marker);
  if (index !== -1 && index < cutIndex) {
    cutIndex = index;
  }
}

email = email.substring(0, cutIndex);

// Remove repeated whitespace
email = email
  .replace(/\n\s*\n/g, "\n")
  .replace(/\s+/g, " ")
  .trim();

return [{
  json: {
    ...$json,
    email
  }
}];
